-- Enclosed in a rolled-back transaction on an isolated Neon test branch.
DO $test$
DECLARE u uuid:=gen_random_uuid();w uuid:=gen_random_uuid();device uuid;other uuid:=gen_random_uuid();result jsonb;t uuid;c uuid;m jsonb;again jsonb;k uuid:=gen_random_uuid();number integer;
BEGIN
 INSERT INTO app_users(id,email,display_name,password_hash) VALUES(u,'mobile-'||u||'@example.test','Mobile fixture','not-a-login-hash');
 INSERT INTO workspaces(id,name,service_mode,created_by) VALUES(w,'Mobile fixture','both',u);
 UPDATE workspace_product_access SET enabled=(product='ai') WHERE workspace_id=w;
 result:=mobile_device_manage(w,'live','begin',NULL,'Fixture',repeat('b',64));device:=(result->>'id')::uuid;
 result:=mobile_device_preview(repeat('b',64));
 IF NOT (result->'products'->>'ai')::boolean OR (result->'products'->>'payments')::boolean THEN RAISE EXCEPTION 'AI-only preview mismatch'; END IF;
 result:=mobile_device_claim(repeat('b',64),decode(repeat('ab',91),'hex'));
 IF result->>'id'<>device::text THEN RAISE EXCEPTION 'device identity changed'; END IF;
 UPDATE workspace_product_access SET enabled=(product='payments') WHERE workspace_id=w;
 result:=mobile_workspace_state(w,'live');
 IF (result->'products'->>'ai')::boolean OR NOT (result->'products'->>'payments')::boolean THEN RAISE EXCEPTION 'product transition stale'; END IF;
 UPDATE workspace_product_access SET enabled=true WHERE workspace_id=w;
 result:=mobile_workspace_state(w,'live');IF NOT (result->'products'->>'ai')::boolean OR NOT (result->'products'->>'payments')::boolean THEN RAISE EXCEPTION 'both transition stale'; END IF;
 c:=inbox_connection(w,'live','wa','fixture-'||w,decode('abcd','hex'));
 PERFORM inbox_ingest(c,'provider-1','customer-1','Fixture customer','Hello','text',now());
 IF inbox_ingest(c,'provider-1','customer-1','Fixture customer','Hello','text',now()) THEN RAISE EXCEPTION 'provider retry duplicated'; END IF;
 SELECT id INTO t FROM inbox_threads WHERE connection_id=c;
 result:=inbox_page(w,'live',device,NULL,NULL,'{}');IF jsonb_array_length(result->'items')<>1 THEN RAISE EXCEPTION 'thread missing'; END IF;
 IF jsonb_array_length(inbox_page(w,'sandbox',device,NULL,NULL,'{}')->'items')<>0 THEN RAISE EXCEPTION 'cross-realm conversation leak'; END IF;
 m:=inbox_action(w,'live',device,t,'send',jsonb_build_object('text','Reply','idempotency_key',k));
 again:=inbox_action(w,'live',device,t,'send',jsonb_build_object('text','Reply','idempotency_key',k));
 IF m->>'id'<>again->>'id' THEN RAISE EXCEPTION 'send idempotency failed'; END IF;
 PERFORM inbox_status(c,'outbound-fixture','seen',now());
 PERFORM inbox_next_send();
 PERFORM inbox_finish_send((m->>'id')::uuid,'outbound-fixture','sent','');
 IF (SELECT state FROM inbox_messages WHERE id=(m->>'id')::uuid)<>'seen' THEN RAISE EXCEPTION 'early provider read event lost'; END IF;
 PERFORM inbox_seen_watermark(c,'customer-1',now()+interval '1 second');
 again:=inbox_action(w,'live',device,t,'send',jsonb_build_object('text','Second reply','idempotency_key',gen_random_uuid()));
 PERFORM inbox_next_send();
 PERFORM inbox_finish_send((again->>'id')::uuid,'second-outbound-fixture','sent','');
 IF (SELECT state FROM inbox_messages WHERE id=(again->>'id')::uuid)<>'seen' THEN RAISE EXCEPTION 'early Messenger watermark lost';END IF;
 IF (SELECT ai_enabled FROM inbox_threads WHERE id=t) THEN RAISE EXCEPTION 'seller reply did not hand off AI'; END IF;
 BEGIN PERFORM inbox_action(w,'live',device,t,'send',jsonb_build_object('text','Other','idempotency_key',k));RAISE EXCEPTION 'idempotency conflict accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 PERFORM inbox_action(w,'live',device,t,'read',jsonb_build_object('sequence',m->>'sequence'));
 result:=inbox_page(w,'live',device,NULL,NULL,'{"unread":true}');IF jsonb_array_length(result->'items')<>0 THEN RAISE EXCEPTION 'unread cursor not durable'; END IF;
 UPDATE inbox_threads SET last_customer_at=now()-interval '25 hours' WHERE id=t;
 BEGIN PERFORM inbox_action(w,'live',device,t,'send',jsonb_build_object('text','Late reply','idempotency_key',gen_random_uuid()));RAISE EXCEPTION 'closed window accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM inbox_page(other,'live',device,t,NULL,'{}');RAISE EXCEPTION 'foreign workspace allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM inbox_register_push(device,decode('abcd','hex'));
 PERFORM inbox_ingest(c,'provider-2','customer-1','Fixture customer','New message','text',now());
 PERFORM set_config('test.mobile_workspace',w::text,true);
 IF NOT has_function_privilege('ekmivo_financial_projection','mobile_workspace_state(uuid,text)','EXECUTE') OR NOT has_function_privilege('ekmivo_financial_projection','inbox_action(uuid,text,uuid,uuid,text,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'actual control pool role cannot execute';END IF;
 IF has_table_privilege('ekmivo_financial_runtime','inbox_connections','SELECT') OR has_table_privilege('ekmivo_financial_runtime','inbox_messages','SELECT') THEN RAISE EXCEPTION 'runtime raw access'; END IF;
 IF (SELECT count(*) FROM inbox_push_jobs WHERE device_id=device)<>1 THEN RAISE EXCEPTION 'push fanout missing'; END IF;
 PERFORM inbox_oauth_begin(repeat('c',64),w,'live',u,'wa');
 BEGIN PERFORM inbox_oauth_consume(repeat('c',64),other);RAISE EXCEPTION 'foreign OAuth actor allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 result:=inbox_oauth_consume(repeat('c',64),u);
 IF result->>'workspace_id'<>w::text THEN RAISE EXCEPTION 'OAuth scope changed';END IF;
 BEGIN PERFORM inbox_oauth_consume(repeat('c',64),u);RAISE EXCEPTION 'OAuth replay allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 UPDATE workspace_product_access SET enabled=false WHERE workspace_id=w;
 result:=mobile_workspace_state(w,'live');IF (result->'products'->>'ai')::boolean OR (result->'products'->>'payments')::boolean THEN RAISE EXCEPTION 'both-off state stale'; END IF;
 BEGIN PERFORM inbox_page(w,'live',device,NULL,NULL,'{}');RAISE EXCEPTION 'AI disabled still readable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM mobile_device_manage(w,'live','revoke',device,'','');
 IF (SELECT authorized FROM mobile_device_key(device)) THEN RAISE EXCEPTION 'revoked device authorized'; END IF;
END $test$;
SELECT true AS products_pairing_tenant_inbox_idempotency_handover_checks_pass;

SET LOCAL ROLE ekmivo_financial_projection;
SELECT mobile_workspace_state(current_setting('test.mobile_workspace')::uuid,'live') IS NOT NULL AS restricted_control_role_pass;
RESET ROLE;
